"use strict";(self.webpackChunkmi_documentacion=self.webpackChunkmi_documentacion||[]).push([["6359"],{1973(e,a,o){o.r(a),o.d(a,{metadata:()=>n,default:()=>u,frontMatter:()=>i,contentTitle:()=>l,toc:()=>t,assets:()=>c});var n=JSON.parse('{"id":"Propuestas/Documento_postmortem","title":"Documento Post-Mortem","description":"Proyecto Autosemec \u2014 Sistema de gesti\xf3n para el taller mec\xe1nico de don Rony Payes","source":"@site/docs/03-Propuestas/Documento_postmortem.md","sourceDirName":"03-Propuestas","slug":"/Propuestas/Documento_postmortem","permalink":"/CA_2S26_G5/docs/Propuestas/Documento_postmortem","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/03-Propuestas/Documento_postmortem.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"Acuerdos y Trade-offs \u2014 Junta Directiva del Proyecto Autosemec","permalink":"/CA_2S26_G5/docs/Propuestas/Acuerdos_tradeoffs"},"next":{"title":"Elevator_pitch","permalink":"/CA_2S26_G5/docs/Propuestas/Elevator_pitch"}}'),s=o(4848),r=o(8453);let i={},l="Documento Post-Mortem",c={},t=[{value:"Proyecto Autosemec \u2014 Sistema de gesti\xf3n para el taller mec\xe1nico de don Rony Payes",id:"proyecto-autosemec--sistema-de-gesti\xf3n-para-el-taller-mec\xe1nico-de-don-rony-payes",level:2},{value:"1. Resumen del incidente",id:"1-resumen-del-incidente",level:2},{value:"2. L\xednea de tiempo (timeline)",id:"2-l\xednea-de-tiempo-timeline",level:2},{value:"3. Impacto",id:"3-impacto",level:2},{value:"4. Causa ra\xedz (T\xe9cnica de los 5 porqu\xe9s)",id:"4-causa-ra\xedz-t\xe9cnica-de-los-5-porqu\xe9s",level:2},{value:"5. Acciones tomadas para solucionarlo",id:"5-acciones-tomadas-para-solucionarlo",level:2},{value:"6. Acciones a futuro",id:"6-acciones-a-futuro",level:2}];function d(e){let a={h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"documento-post-mortem",children:"Documento Post-Mortem"})}),"\n",(0,s.jsx)(a.h2,{id:"proyecto-autosemec--sistema-de-gesti\xf3n-para-el-taller-mec\xe1nico-de-don-rony-payes",children:"Proyecto Autosemec \u2014 Sistema de gesti\xf3n para el taller mec\xe1nico de don Rony Payes"}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"1-resumen-del-incidente",children:"1. Resumen del incidente"}),"\n",(0,s.jsx)(a.p,{children:"Durante las primeras semanas de implementaci\xf3n de la soluci\xf3n tecnol\xf3gica para el taller mec\xe1nico Autosemec, propiedad de don Rony Payes, el equipo de proyecto enfrent\xf3 un incidente que puso en riesgo la viabilidad de todo el plan. El problema de fondo fue claro: el equipo ten\xeda cinco propuestas buenas sobre la mesa \u2014 control de repuestos, presupuesto claro, expediente digital, agenda inteligente y asistente en el celular \u2014 pero no pod\xeda construirlas todas con el tiempo y el dinero disponibles. Hab\xeda que decidir qu\xe9 se hac\xeda, hasta d\xf3nde se llegaba y qu\xe9 se sacrificaba."}),"\n",(0,s.jsx)(a.p,{children:"Lo que comenz\xf3 como diferencias normales de criterio entre los integrantes del equipo fue escalando d\xeda a d\xeda hasta convertirse en tres conflictos concretos que amenazaron con paralizar el proyecto."}),"\n",(0,s.jsx)(a.p,{children:'El primer conflicto fue la tensi\xf3n entre tiempo y costo contra calidad. Carlos, responsable del plazo y presupuesto, ven\xeda presionando desde los primeros d\xedas para entregar resultados r\xe1pidos y visibles. Quer\xeda que en cuatro semanas don Rony ya tuviera algo funcionando. Hassan y Naomi, por su parte, insist\xedan en que entregar funciones a medias o sin pruebas ser\xeda peor que no entregar nada, porque si el sistema fallaba, don Rony perder\xeda la confianza y simplemente dejar\xeda de usarlo. Esta diferencia de visi\xf3n gener\xf3 roces que fueron subiendo de tono con el paso de los d\xedas, hasta que en una discusi\xf3n directa Carlos dijo que "siempre es lo mismo con los t\xe9cnicos: todo es imposible", momento en el que Dennis tuvo que intervenir para reconducir la conversaci\xf3n.'}),"\n",(0,s.jsx)(a.p,{children:"El segundo conflicto fue el crecimiento del alcance. A medida que avanzaban los d\xedas y el equipo iba definiendo las funcionalidades, Aimar \u2014 quien representaba a don Rony \u2014 fue introduciendo solicitudes que no estaban en la entrevista original. Primero fueron detalles menores, pero luego pidi\xf3 que se agregaran ventas y facturas, lo cual implicaba un m\xf3dulo completo con reglas de impuestos y m\xfaltiples pantallas. Esto tom\xf3 por sorpresa al equipo, porque incorporar eso habr\xeda puesto en riesgo todo lo que ya se hab\xeda planificado. Carlos reaccion\xf3 con firmeza, Hassan advirti\xf3 que era otro sistema completo, y Naomi lo registr\xf3 como un riesgo de alcance sin control."}),"\n",(0,s.jsx)(a.p,{children:'El tercer conflicto fue la comunicaci\xf3n poco clara del cliente. A lo largo de los d\xedas, Aimar tend\xeda a responder con frases como "lo que ustedes digan est\xe1 bien" o "ustedes son los expertos", evitando comprometerse con respuestas directas. El problema era que don Rony s\xed ten\xeda prioridades definidas y un tope de presupuesto de Q6,000 que Aimar no comunic\xf3 con claridad hasta que Dennis lo confront\xf3 directamente. Esta falta de informaci\xf3n retras\xf3 decisiones clave y provoc\xf3 que el equipo trabajara durante d\xedas sobre opciones que resultaron ser inviables desde el inicio.'}),"\n",(0,s.jsx)(a.p,{children:"La combinaci\xf3n de estos tres conflictos \u2014 la presi\xf3n por velocidad chocando con la defensa de la calidad, un alcance que crec\xeda sin control y un canal de comunicaci\xf3n con el cliente que no transmit\xeda la informaci\xf3n completa \u2014 llev\xf3 al equipo a convocar una junta de emergencia para resolver la situaci\xf3n antes de que el proyecto se descarrilara por completo."}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"2-l\xednea-de-tiempo-timeline",children:"2. L\xednea de tiempo (timeline)"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Lunes 8:00 AM \u2013 Arranque del proyecto:\xa0El equipo se reuni\xf3 por primera vez para revisar el informe de la entrevista con don Rony. Se identificaron los problemas principales del taller: p\xe9rdida de tiempo buscando repuestos y recogiendo carros, informaci\xf3n guardada solo en la memoria y el tel\xe9fono de don Rony, presupuestos que no quedaban por escrito, falta de control del espacio en el taller y errores por distracci\xf3n. Cada integrante comenz\xf3 a trabajar en su propuesta individual."}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Martes 10:00 AM \u2013 Primeras propuestas en borrador:\xa0Carlos present\xf3 su idea de control de repuestos, Hassan la de presupuesto claro por mensaje, Aimar la del expediente digital, Naomi la de agenda inteligente con control de espacio, y Dennis la del asistente en el celular. Las cinco propuestas eran buenas, pero ya se notaba que no cab\xedan todas en un solo plan."}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Mi\xe9rcoles 9:30 AM \u2013 Primeras se\xf1ales de tensi\xf3n:\xa0Carlos empez\xf3 a presionar para definir fechas concretas. Pidi\xf3 que se entregaran repuestos y presupuestos en cuatro semanas. Hassan expres\xf3 su preocupaci\xf3n de que hacer cinco funciones en ese plazo resultar\xeda en entregas a medias. Naomi respald\xf3 a Hassan y advirti\xf3 que un sistema que guardara mal los datos o calculara mal un presupuesto har\xeda m\xe1s da\xf1o que no tener sistema. Carlos interpret\xf3 esto como resistencia y el tono de las conversaciones empez\xf3 a subir."}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:'Jueves 11:00 AM \u2013 Aimar introduce cambios de alcance:\xa0Aimar comunic\xf3 que don Rony tambi\xe9n quer\xeda ventas y facturas, funcionalidades que no hab\xedan aparecido en la entrevista original. Carlos reaccion\xf3 con firmeza: "Si cada semana agregamos algo nuevo, nunca terminamos." Hassan se\xf1al\xf3 que ventas y facturas era otro sistema completo, con reglas de impuestos y muchas pantallas. Naomi lo registr\xf3 en su reporte de riesgos como alcance que crec\xeda sin control. Aimar se retrajo diciendo "si no se puede, no pasa nada", pero la tensi\xf3n qued\xf3 en el aire.'}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:'Viernes 9:00 AM \u2013 Comunicaci\xf3n ambigua del cliente se vuelve un problema:\xa0El equipo necesitaba saber el presupuesto m\xe1ximo de don Rony para poder tomar decisiones. Aimar respondi\xf3 con evasivas: "lo que ustedes digan", "ustedes son los expertos". Dennis not\xf3 que Aimar evitaba dar respuestas concretas y que esto estaba retrasando decisiones fundamentales. Mientras tanto, Hassan calcul\xf3 que las cinco funciones completas costar\xedan Q7,000 en ocho semanas o Q8,500 en cuatro semanas, pero sin saber el tope del cliente, no hab\xeda forma de decidir.'}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:'Lunes 2:00 PM \u2013 Escalada del conflicto tiempo vs. calidad:\xa0En una discusi\xf3n sobre prioridades, Carlos perdi\xf3 la paciencia y dijo: "Siempre es lo mismo con ustedes, los t\xe9cnicos: todo es imposible. Yo estoy pidiendo resultados, no un discurso." Dennis intervino de inmediato, le pidi\xf3 que separara la persona del problema y que reformulara su mensaje. Carlos respir\xf3, baj\xf3 el tono y se disculp\xf3: "Tienes raz\xf3n. Lo reformulo: me preocupa que nos pasemos de fecha y de presupuesto. Necesito que me digan qu\xe9 s\xed se puede entregar en cuatro semanas." Naomi respondi\xf3 que no aprobar\xeda ninguna entrega sin pruebas, pero propuso que fueran solo dos d\xedas de pruebas enfocadas en lo cr\xedtico, no tres meses como Carlos tem\xeda.'}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Martes 8:30 AM \u2013 Dennis convoca junta de emergencia:\xa0Ante la acumulaci\xf3n de conflictos sin resolver, Dennis decidi\xf3 convocar una junta formal con todos los integrantes para el d\xeda siguiente. El objetivo era claro: no salir de esa reuni\xf3n sin acuerdos escritos y firmados sobre qu\xe9 se iba a construir, en cu\xe1nto tiempo, con qu\xe9 presupuesto y qu\xe9 se dejaba fuera."}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:'Mi\xe9rcoles 9:00 AM \u2013 Junta directiva: apertura y revelaci\xf3n del presupuesto real:\xa0Dennis abri\xf3 la reuni\xf3n estableciendo reglas: hablar uno a la vez, con respeto, y salir con acuerdos claros. Confront\xf3 directamente a Aimar sobre el presupuesto: "Necesito que seas claro porque esto cambia la decisi\xf3n. \xbfQ6,000 es el tope, s\xed o no?" Aimar finalmente confirm\xf3 que s\xed, que Q6,000 era el tope y que don Rony prefer\xeda entregas por partes. Con ese dato sobre la mesa, qued\xf3 claro que las cinco funciones completas no cab\xedan en el presupuesto sin bajar la calidad.'}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Mi\xe9rcoles 10:30 AM \u2013 Junta directiva: resoluci\xf3n del alcance:\xa0Dennis le pregunt\xf3 a Aimar qu\xe9 quer\xeda resolver realmente don Rony con las ventas y facturas. Aimar aclar\xf3 que no necesitaba facturaci\xf3n formal, solo saber cu\xe1nto cobr\xf3 por cada trabajo y cu\xe1nto le deb\xedan. Hassan propuso registrar eso dentro del presupuesto, sin costo adicional ni cambio en el calendario."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(a.p,{children:"El equipo tambi\xe9n acord\xf3 que el hijo de don Rony usar\xeda el sistema, y Naomi propuso que cada anotaci\xf3n quedara con nombre y hora para trazabilidad."}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:'Mi\xe9rcoles 12:00 PM \u2013 Junta directiva: negociaci\xf3n y trade-offs:\xa0Hassan propuso dividir el proyecto en dos fases. La fase 1 incluir\xeda expediente digital, lista de repuestos, presupuesto con registro de cobro y una agenda simple, todo dentro del asistente en el celular, en seis semanas por Q5,800. Carlos pidi\xf3 reducir a cinco semanas, pero Naomi se neg\xf3 a firmar si se sacrificaban las pruebas. Propuso hacer pruebas en paralelo al desarrollo, lo cual permit\xeda mantener las seis semanas sin recortar calidad. Carlos acept\xf3: "Es m\xe1s tiempo del que quer\xeda, pero se ve un plan serio."'}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Mi\xe9rcoles 1:30 PM \u2013 Junta directiva: calendario de entregas:\xa0Naomi defini\xf3 el plan: Semana 2, expediente digital y lista de repuestos; Semana 4, presupuesto con cobro y bot\xf3n de mensaje; Semana 6, agenda simple con control de espacio, ajustes y capacitaci\xf3n. Aimar expres\xf3 su miedo de que don Rony no supiera usar el sistema. Hassan incluy\xf3 una sesi\xf3n de capacitaci\xf3n en el taller y un mes de soporte por mensaje, dentro del presupuesto de Q5,800."}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Mi\xe9rcoles 3:00 PM \u2013 Junta directiva: acuerdos firmados y cierre:\xa0Se firmaron seis acuerdos que cubr\xedan alcance, entregas bisemanales, control de cambios, protecci\xf3n de datos, capacitaci\xf3n con soporte por un mes, y se\xf1ales de alerta. Cada integrante asumi\xf3 una responsabilidad concreta y firm\xf3 el acta. El proyecto qued\xf3 Q200 por debajo del tope de don Rony, dejando un margen para imprevistos."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)("img",{width:"1280",height:"905",alt:"LineaTime",src:"https://github.com/user-attachments/assets/cc081746-3d45-4420-92b4-abc0705aafa6"}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"3-impacto",children:"3. Impacto"}),"\n",(0,s.jsx)(a.p,{children:"Los tres conflictos que se desarrollaron a lo largo de los d\xedas tuvieron un impacto real sobre el proyecto, el equipo y el cliente."}),"\n",(0,s.jsx)(a.p,{children:"Impacto sobre el equipo de desarrollo:\r\nLa tensi\xf3n acumulada entre Carlos y el resto del equipo t\xe9cnico deterior\xf3 la din\xe1mica de trabajo durante casi una semana y media. El choque entre la urgencia por entregar r\xe1pido y la defensa de la calidad gener\xf3 un ambiente donde las propuestas se recib\xedan con desconfianza en lugar de colaboraci\xf3n. Hubo un momento el lunes de la segunda semana en que la comunicaci\xf3n se volvi\xf3 agresiva y Dennis tuvo que mediar para evitar que la relaci\xf3n profesional se da\xf1ara. Si este conflicto no se hubiera resuelto en la junta del mi\xe9rcoles, el equipo habr\xeda seguido trabajando bajo presi\xf3n excesiva, aumentando la probabilidad de errores, entregas defectuosas y posiblemente la renuncia de alg\xfan integrante."}),"\n",(0,s.jsx)(a.p,{children:"Impacto sobre el alcance del proyecto:\r\nLa solicitud de Aimar el jueves de incluir ventas y facturas amenaz\xf3 con desbordar el alcance de todo el proyecto. Si se hubiera aceptado sin an\xe1lisis, el equipo habr\xeda asumido un m\xf3dulo completo con reglas de impuestos y m\xfaltiples pantallas que no estaba planificado, lo que habr\xeda retrasado las entregas y superado el presupuesto. El impacto real fue que durante varios d\xedas el equipo discuti\xf3 sobre funcionalidades que no correspond\xedan al problema original, perdiendo tiempo valioso de planificaci\xf3n. Gracias a la intervenci\xf3n de Dennis durante la junta, se descubri\xf3 que la necesidad real era mucho m\xe1s simple \u2014 registrar cu\xe1nto se cobr\xf3 y cu\xe1nto se deb\xedan \u2014 y se integr\xf3 sin costo adicional."}),"\n",(0,s.jsx)(a.p,{children:"Impacto sobre el cliente (don Rony Payes):\r\nLa comunicaci\xf3n ambigua de Aimar retras\xf3 decisiones fundamentales desde el martes de la primera semana hasta el mi\xe9rcoles de la segunda. El equipo no supo hasta la junta de emergencia que el presupuesto ten\xeda un tope de Q6,000, lo que signific\xf3 que las primeras opciones discutidas (Q7,000 y Q8,500) eran inviables desde el inicio. Si Aimar no hubiera aclarado esto, el equipo podr\xeda haber planificado y comenzado a construir una soluci\xf3n que don Rony no pod\xeda pagar, generando frustraci\xf3n, retrabajo y posiblemente la cancelaci\xf3n del proyecto. Adem\xe1s, don Rony estuvo varios d\xedas sin recibir informaci\xf3n clara sobre qu\xe9 iba a recibir ni cu\xe1ndo, lo que pudo haber erosionado su confianza en el equipo."}),"\n",(0,s.jsx)(a.p,{children:"Impacto sobre el calendario:\r\nLa combinaci\xf3n de los tres conflictos consumi\xf3 una semana y media que debi\xf3 haberse dedicado a la construcci\xf3n del sistema. Lo que Carlos esperaba resolver en cuatro semanas termin\xf3 siendo un proyecto de seis semanas dividido en fases, con entregas cada dos semanas y pruebas en paralelo. Aunque el resultado final fue un plan m\xe1s s\xf3lido y realista, el retraso en la toma de decisiones signific\xf3 que el proyecto arranc\xf3 tarde y con menos margen para imprevistos."}),"\n",(0,s.jsx)(a.p,{children:'Impacto indirecto sobre la confianza:\r\nSi los conflictos no se hubieran abordado abiertamente en la junta de emergencia del mi\xe9rcoles, el equipo habr\xeda salido con acuerdos fr\xe1giles basados en suposiciones. La falta de claridad en la comunicaci\xf3n del cliente, combinada con expectativas de velocidad poco realistas y un alcance en crecimiento, habr\xeda generado incumplimientos en las primeras entregas, erosionando la confianza tanto dentro del equipo como con don Rony. El taller habr\xeda terminado con un sistema a medias que nadie usar\xeda, confirmando el temor de Naomi: "Un sistema perfecto que nadie usa es un sistema fallido."'}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"4-causa-ra\xedz-t\xe9cnica-de-los-5-porqu\xe9s",children:"4. Causa ra\xedz (T\xe9cnica de los 5 porqu\xe9s)"}),"\n",(0,s.jsx)(a.p,{children:"El problema inicial: El equipo tard\xf3 una semana y media en llegar a un acuerdo sobre el alcance y el presupuesto del sistema para Autosemec, generando tensi\xf3n, discusiones agresivas y retrasos en el calendario de desarrollo."}),"\n",(0,s.jsx)(a.p,{children:"\xbfPor qu\xe9 el equipo tard\xf3 tanto en llegar a un acuerdo y hubo tanta tensi\xf3n?\r\nPorque hab\xeda una discusion sobre presupuestos irreales (Q7,000 y Q8,500) y exigencias de tiempo imposibles (cuatro semanas para 5 m\xf3dulos completos), sin saber qu\xe9 funciones descartar."}),"\n",(0,s.jsx)(a.p,{children:"\xbfPor qu\xe9 discut\xedan sobre presupuestos irreales sin saber qu\xe9 funciones descartar?\r\nPorque no conoc\xedan el tope m\xe1ximo real de dinero que don Rony pod\xeda pagar ni sus prioridades fundamentales."}),"\n",(0,s.jsx)(a.p,{children:'\xbfPor qu\xe9 no conoc\xedan el tope m\xe1ximo real de dinero ni las prioridades?\r\nPorque Aimar, quien actuaba como enlace con el cliente, respond\xeda de forma ambigua ("lo que ustedes digan", "ustedes son los expertos") y no comunicaba las limitantes reales.'}),"\n",(0,s.jsx)(a.p,{children:"\xbfPor qu\xe9 Aimar se comunicaba de forma ambigua y no daba los datos reales?\r\nPorque el equipo no estableci\xf3 desde el inicio reglas estrictas de comunicaci\xf3n ni un proceso formal de recolecci\xf3n de requisitos donde el cliente tuviera que firmar o aprobar un documento de l\xedmites y alcance."}),"\n",(0,s.jsx)(a.p,{children:"\xbfPor qu\xe9 no se establecieron esas reglas formales al inicio?\r\n(Causa Ra\xedz): Falla t\xe9cnica y de procesos en la gesti\xf3n inicial. El equipo arranc\xf3 la planificaci\xf3n de soluciones bas\xe1ndose \xfanicamente en suposiciones t\xe9cnicas individuales, sin validar formalmente los l\xedmites del negocio (presupuesto y capacidades del usuario) como primer paso obligatorio, lo que provoc\xf3 que trabajaran a ciegas y permiti\xf3 que la falta de asertividad en la comunicaci\xf3n desviara el enfoque del proyecto."}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"5-acciones-tomadas-para-solucionarlo",children:"5. Acciones tomadas para solucionarlo"}),"\n",(0,s.jsx)(a.p,{children:"Durante el momento cr\xedtico del incidente (cuando la tensi\xf3n entre tiempo y calidad amenazaba con disolver el equipo), se aplicaron las siguientes mitigaciones para poder llegar a un acuerdo:"}),"\n",(0,s.jsx)(a.p,{children:'Intervenci\xf3n de mediaci\xf3n en tiempo real: Dennis intervino directamente en la discusi\xf3n m\xe1s cr\xedtica para frenar el choque personal entre Carlos y el equipo t\xe9cnico, obligando a replantear la comunicaci\xf3n bajo la regla de "separar a la persona del problema".'}),"\n",(0,s.jsx)(a.p,{children:"Convocatoria de una junta de emergencia: Se detuvo inmediatamente todo el desarrollo individual y se convoc\xf3 una junta directiva de car\xe1cter obligatorio para alinear visiones."}),"\n",(0,s.jsx)(a.p,{children:"Confrontaci\xf3n directa de requisitos: Durante la junta, se presion\xf3 al enlace del cliente (Aimar) para que revelara el presupuesto real, confirmando el tope de Q6,000, lo que detuvo inmediatamente las discusiones sobre propuestas inviables."}),"\n",(0,s.jsx)(a.p,{children:'Negociaci\xf3n de Trade-Offs (Parche al calendario): Se aplic\xf3 un cambio dr\xe1stico en el flujo de trabajo pasando de un modelo de "entrega total" a uno de "fases divisibles", acordando una primera fase de 6 semanas por Q5,800, con pruebas cada 2 semanas para no sacrificar calidad.'}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"6-acciones-a-futuro",children:"6. Acciones a futuro"}),"\n",(0,s.jsx)(a.p,{children:'Implementaci\xf3n de un "Registro de Requisitos Firmada": Antes de dise\xf1ar cualquier soluci\xf3n, el cliente deber\xe1 firmar un documento de restricciones que incluya el presupuesto m\xe1ximo, el tiempo l\xedmite y las 3 funciones prioritarias innegociables. Ning\xfan desarrollador comenzar\xe1 a trabajar sin este documento.'}),"\n",(0,s.jsx)(a.p,{children:"Sistema de Control de Cambios Estricto: Toda solicitud de nueva funcionalidad (como ocurri\xf3 con el m\xf3dulo de ventas y facturas) entrar\xe1 a una bit\xe1cora de revisi\xf3n t\xe9cnica. Ning\xfan requerimiento nuevo se aceptar\xe1 verbalmente; deber\xe1 pasar por un an\xe1lisis de impacto en tiempo/costo antes de ser aprobado o rechazado."}),"\n",(0,s.jsx)(a.p,{children:"Se\xf1ales de Alerta Preventivas (Monitoreo del Proyecto): Se programar\xe1n revisiones semanales obligatorias (alertas). Si el presupuesto consumido llega a Q5,500 antes de la semana 5, o si una entrega no supera las pruebas de calidad, el trabajo se detiene y se convoca una reuni\xf3n de emergencia en 48 horas."}),"\n",(0,s.jsx)(a.p,{children:"Pruebas en Paralelo Institucionalizadas: El flujo de trabajo del equipo adoptar\xe1 oficialmente la metodolog\xeda de pruebas simult\xe1neas; el equipo de calidad testear\xe1 cada subm\xf3dulo mientras se desarrolla el siguiente, evitando as\xed los cuellos de botella al final del ciclo."})]})}function u(e={}){let{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,a,o){o.d(a,{R:()=>i,x:()=>l});var n=o(6540);let s={},r=n.createContext(s);function i(e){let a=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function l(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(r.Provider,{value:a},e.children)}}}]);